def gen(rng):
    def fmt(n, k, sw):
        return f'{n} {len(sw)} {k}\n' + '\n'.join(f'{a} {b}' for a, b in sw)
    tests = [fmt(1, 1, [(1, 1)]), fmt(2, 1, [(1, 2)]), fmt(2, 2, [(1, 2), (2, 1)]), fmt(3, 3, [(2, 2)]),
             fmt(5, 2, [(1, 2), (2, 3), (1, 5)]), fmt(4, 4, [(1, 4), (4, 2)])]
    for n in (2, 3, 4, 6, 9, 15, 30):
        for _ in range(3):
            q = rng.randint(1, 25)
            tests.append(fmt(n, rng.randint(1, n), [(rng.randint(1, n), rng.randint(1, n)) for _ in range(q)]))
    N = 100000
    tests.append(fmt(N, rng.randint(1, N), [(rng.randint(1, N), rng.randint(1, N)) for _ in range(N)]))
    tests.append(fmt(N, N, [(1 + (i % N), N - (i % N)) for i in range(N)]))
    tests.append(fmt(N, 1, [(N - i, 1) for i in range(N)]))
    tests.append(fmt(N, N // 2, [(rng.randint(N - 50, N), rng.randint(1, N)) for _ in range(N)]))
    return tests

